package com.booksyde.controller; import com.booksyde.dto.request.UpdateProfileRequest; import com.booksyde.dto.response.ProfileResponse; import com.booksyde.service.ProfileService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/profiles") public class ProfileController {private final ProfileService profiles; public ProfileController(ProfileService profiles){this.profiles=profiles;} @GetMapping("/me") public ProfileResponse me(@AuthenticationPrincipal Jwt jwt){return profiles.get(UUID.fromString(jwt.getSubject()));} @PutMapping("/me") public ProfileResponse update(@Valid @RequestBody UpdateProfileRequest r,@AuthenticationPrincipal Jwt jwt){return profiles.update(UUID.fromString(jwt.getSubject()),r);}}
